<script lang="ts" setup>
import { onMounted, ref } from 'vue';
import { Page } from '@vben/common-ui';
import { getShopSettlementPage, generateShopSettlement, auditShopSettlement, confirmShopSettlement, type ShopSettlement } from '#/api/mall/trade/settlement';
import { getShopList, type MallShopApi } from '#/api/mall/product/shop';
const rows = ref<ShopSettlement[]>([]); const shops = ref<MallShopApi.Shop[]>([]); const shopId = ref<number>(); const loading = ref(false); const commissionRate = ref(500);
async function refresh() { loading.value = true; try { const result = await getShopSettlementPage({ pageNo: 1, pageSize: 100, shopId: shopId.value }); rows.value = (result as any).list || (result as any).items || []; } finally { loading.value = false; } }
async function generate() { if (!shopId.value) return; const end = new Date(); const start = new Date(end); start.setMonth(start.getMonth() - 1); await generateShopSettlement({ shopId: shopId.value, periodStartTime: start.toISOString().slice(0, 19), periodEndTime: end.toISOString().slice(0, 19), commissionRate: commissionRate.value }); await refresh(); }
async function audit(row: ShopSettlement) { await auditShopSettlement({ id: row.id!, status: 20, auditRemark: '后台审核通过' }); await refresh(); }
async function confirm(row: ShopSettlement) { await confirmShopSettlement(row.id!); await refresh(); }
onMounted(async () => { shops.value = await getShopList(); await refresh(); });
</script>
<template><Page auto-content-height><div class="p-4"><div class="mb-4 flex items-center gap-3"><span>店铺</span><select v-model="shopId" class="h-8 rounded border px-2" @change="refresh"><option :value="undefined">全部店铺</option><option v-for="shop in shops" :key="shop.id" :value="shop.id">{{ shop.name }}</option></select><span>佣金万分比</span><input v-model.number="commissionRate" type="number" min="0" max="10000" class="h-8 w-24 rounded border px-2"><button class="rounded bg-primary px-3 py-1 text-white" :disabled="!shopId" @click="generate">生成近月结算</button><button class="rounded border px-3 py-1" @click="refresh">刷新</button></div><table class="w-full text-left text-sm"><thead><tr><th class="p-2">结算单号</th><th class="p-2">店铺</th><th class="p-2">周期</th><th class="p-2">订单数</th><th class="p-2">应结金额</th><th class="p-2">状态</th><th class="p-2">操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-t"><td class="p-2">{{ row.no }}</td><td class="p-2">{{ row.shopName }}</td><td class="p-2">{{ row.periodStartTime }} ~ {{ row.periodEndTime }}</td><td class="p-2">{{ row.orderCount }}</td><td class="p-2">{{ ((row.settlementAmount || 0) / 100).toFixed(2) }} 元</td><td class="p-2">{{ row.status === 10 ? '待审核' : row.status === 20 ? '已审核' : row.status === 30 ? '已结算' : '已拒绝' }}</td><td class="p-2"><button v-if="row.status === 10" class="mr-2 text-primary" @click="audit(row)">审核</button><button v-if="row.status === 20" class="text-primary" @click="confirm(row)">确认结算</button></td></tr><tr v-if="!loading && !rows.length"><td colspan="7" class="p-6 text-center text-gray-400">暂无结算单</td></tr></tbody></table></div></Page></template>

